import 'dart:async';import 'dart:typed_data';import 'dart:math';import 'package:flutter/foundation.dart';class FileChunk {  final String fileId;  final int chunkIndex;  final int totalChunks;  final Uint8List data;  final Uint8List hash;  final String sourceNodeId;  final DateTime timestamp;  FileChunk({    required this.fileId,    required this.chunkIndex,    required this.totalChunks,    required this.data,    required this.hash,    required this.sourceNodeId,    required this.timestamp,  });  bool get isLast => chunkIndex == totalChunks - 1;  int get size => data.length;  Map<String, dynamic> toJson() => {        'fileId': fileId,        'chunkIndex': chunkIndex,        'totalChunks': totalChunks,        'hash': hash.toList(),        'sourceNodeId': sourceNodeId,        'timestamp': timestamp.toIso8601String(),      };}class DistributedFile {  final String id;  final String originalName;  final int totalSize;  final int chunkSize;  final int totalChunks;  final Uint8List originalHash;  final String ownerId;  final DateTime createdAt;  final Map<int, Set<String>> chunkLocations;  final Map<int, Uint8List> availableChunks;  final String priority;  DistributedFile({    required this.id,    required this.originalName,    required this.totalSize,    required this.chunkSize,    required this.totalChunks,    required this.originalHash,    required this.ownerId,    required this.createdAt,    required this.chunkLocations,    required this.availableChunks,    this.priority = 'normal',  });  int get replicationFactor => chunkLocations.isEmpty      ? 0      : chunkLocations.values          .map((s) => s.length)          .reduce((a, b) => a > b ? a : b);  bool get isComplete => availableChunks.length == totalChunks;  Map<String, dynamic> toJson() => {        'id': id,        'originalName': originalName,        'totalSize': totalSize,        'chunkSize': chunkSize,        'totalChunks': totalChunks,        'originalHash': originalHash.toList(),        'ownerId': ownerId,        'createdAt': createdAt.toIso8601String(),        'chunkLocations':            chunkLocations.map((k, v) => MapEntry(k.toString(), v.toList())),        'availableChunks': availableChunks.keys.toList(),        'priority': priority,        'isComplete': isComplete,      };}class DistributedStorage {  final Map<String, DistributedFile> _files = {};  final Map<String, Map<int, Uint8List>> _localChunks = {};  final Random _random = Random.secure();  static const int _defaultChunkSize = 16 * 1024;  static const int _redundancyFactor = 3;  static const int _maxStorageMB = 500;  int _usedStorageBytes = 0;  final _storageController = StreamController<DistributedFile>.broadcast();  Stream<DistributedFile> get storageStream => _storageController.stream;  String distributeFile({    required Uint8List data,    required String originalName,    required String ownerId,    int chunkSize = _defaultChunkSize,    String priority = 'normal',  }) {    final fileId = 'FILE_${DateTime.now().millisecondsSinceEpoch}';    final totalChunks = (data.length / chunkSize).ceil();    final hash = _computeHash(data);    final chunkLocations = <int, Set<String>>{};    final emptySet = <String>{ownerId};    for (int i = 0; i < totalChunks; i++) {      chunkLocations[i] = emptySet;    }    final availableChunks = <int, Uint8List>{};    for (int i = 0; i < totalChunks; i++) {      final start = i * chunkSize;      final end =          (start + chunkSize > data.length) ? data.length : start + chunkSize;      availableChunks[i] = Uint8List.fromList(data.sublist(start, end));    }    final file = DistributedFile(      id: fileId,      originalName: originalName,      totalSize: data.length,      chunkSize: chunkSize,      totalChunks: totalChunks,      originalHash: hash,      ownerId: ownerId,      createdAt: DateTime.now(),      chunkLocations: chunkLocations,      availableChunks: availableChunks,      priority: priority,    );    _files[fileId] = file;    _localChunks[fileId] = Map.from(availableChunks);    _usedStorageBytes += data.length;    _storageController.add(file);    debugPrint('File distributed: $originalName ($totalChunks chunks)');    return fileId;  }  Uint8List _computeHash(Uint8List data) {    final hash = Uint8List(32);    for (int i = 0; i < data.length; i++) {      hash[i % 32] = (hash[i % 32] + data[i]) % 256;    }    return hash;  }  void addChunkLocation(String fileId, int chunkIndex, String nodeId) {    final file = _files[fileId];    if (file == null) return;    file.chunkLocations[chunkIndex] ??= {};    file.chunkLocations[chunkIndex]!.add(nodeId);    _storageController.add(file);  }  void storeChunk(      String fileId, int chunkIndex, Uint8List data, String nodeId) {    _localChunks[fileId] ??= {};    _localChunks[fileId]![chunkIndex] = data;    addChunkLocation(fileId, chunkIndex, nodeId);  }  Uint8List? retrieveChunk(String fileId, int chunkIndex) {    return _localChunks[fileId]?[chunkIndex];  }  Uint8List? reconstructFile(String fileId) {    final file = _files[fileId];    if (file == null) return null;    final chunks = <int, Uint8List>{};    for (final entry        in _localChunks[fileId]?.entries ?? <int, Uint8List>{}.entries) {      chunks[entry.key] = entry.value;    }    if (chunks.length != file.totalChunks) return null;    final sortedIndices = chunks.keys.toList()..sort();    final result = <int>[];    for (final index in sortedIndices) {      result.addAll(chunks[index]!);    }    return Uint8List.fromList(result);  }  List<String> getFileChunks(String fileId) {    final file = _files[fileId];    if (file == null) return [];    final available = <String>[];    for (int i = 0; i < file.totalChunks; i++) {      if (file.chunkLocations[i]?.isNotEmpty ?? false) {        available.add('Chunk $i: ${file.chunkLocations[i]!.join(', ')}');      }    }    return available;  }  DistributedFile? getFile(String fileId) => _files[fileId];  List<DistributedFile> getFilesByOwner(String ownerId) {    return _files.values.where((f) => f.ownerId == ownerId).toList();  }  List<DistributedFile> getAvailableFiles() {    return _files.values.where((f) => f.isComplete).toList();  }  Map<String, dynamic> getStatistics() {    final totalChunks =        _files.values.fold<int>(0, (sum, f) => sum + f.totalChunks);    final storedChunks =        _localChunks.values.fold<int>(0, (sum, c) => sum + c.length);    return {      'totalFiles': _files.length,      'completeFiles': _files.values.where((f) => f.isComplete).length,      'totalChunks': totalChunks,      'storedChunks': storedChunks,      'storageUsedMB': (_usedStorageBytes / (1024 * 1024)).round(),      'maxStorageMB': _maxStorageMB,    };  }  void dispose() {    _storageController.close();  }}